// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for many accounts: rotation, caps percent, first-run move, sequential run, skips for halted accounts, the two-safety-stops rule
// Flo: fake runner per account (no browser) > assert order, results, halt marks in each account's own db, nothing shared
// I/O: scratch dir + sqlite (no Chrome) > pass or fail (no leaks)
// Run: zig build test -Dfile=ru-acct-main-test.zig
// ===================================================================
const std = @import("std"); const acct = @import("ru-acct-main.zig"); const conf = @import("cf-conf-load.zig"); const data = @import("st-stat-data.zig");
const Fake = struct { seen: std.ArrayList([]const u8) = .empty, aren: std.mem.Allocator, root: []const u8, halt_id: []const u8 = "", halt_why: []const u8 = "challenge", code_id: []const u8 = "", code: u8 = 3, naps: u32 = 0, lines: u32 = 0 };
fn stor(al: std.mem.Allocator, root: []const u8, id: []const u8) !data.Stor { const dir = try std.fs.path.join(al, &.{ root, "acct", id, "stat" }); try std.Io.Dir.cwd().createDirPath(std.testing.io, dir); return data.Stor.open(al, try std.fs.path.joinZ(al, &.{ dir, "za-stat.db" })); }
fn setHalt(al: std.mem.Allocator, root: []const u8, id: []const u8, why: []const u8) !void { var sto = try stor(al, root, id); defer sto.close(); try sto.haltSet(1, why); }
fn runF(px: ?*anyopaque, id: []const u8) anyerror!u8 { const fk: *Fake = @ptrCast(@alignCast(px.?)); try fk.seen.append(fk.aren, id); if (std.mem.eql(u8, id, fk.halt_id)) { try setHalt(fk.aren, fk.root, id, fk.halt_why); return error.Halted; } if (std.mem.eql(u8, id, fk.code_id)) return fk.code; return 0; }
fn sayF(px: ?*anyopaque, _: []const u8) void { const fk: *Fake = @ptrCast(@alignCast(px.?)); fk.lines += 1; }
var naps: u32 = 0;
fn napF(_: std.Io, _: u64) void { naps += 1; }
fn envOf(fk: *Fake, al: std.mem.Allocator, ids: []const []const u8, now: i64, rng: *std.Random.DefaultPrng) acct.Env { return .{ .aren = al, .iozz = std.testing.io, .cfg = .{}, .root = fk.root, .ids = ids, .now = now, .rng = rng, .ctx = fk, .run = runF, .say = sayF, .nap = napF }; }
fn rootOf(tmp: *std.testing.TmpDir, al: std.mem.Allocator) ![]u8 { return std.fmt.allocPrint(al, ".zig-cache/tmp/{s}", .{tmp.sub_path}); }
test "order rotates by day" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const ids = [_][]const u8{ "a", "b", "c" }; const o0 = try acct.order(aren.allocator(), &ids, 0); try std.testing.expectEqualStrings("a", o0[0]); const o1 = try acct.order(aren.allocator(), &ids, 86400000); try std.testing.expectEqualStrings("b", o1[0]); try std.testing.expectEqualStrings("a", o1[2]); }
test "caps percent scales every capz key, keeps 0 as 0, never drops a live cap to 0" { const cfg: conf.Conf = .{}; const half = acct.applyScal(cfg, 50); try std.testing.expectEqual(@as(u32, 10), half.capz_send_hour); try std.testing.expectEqual(@as(u32, 60), half.capz_send_dayz); const tiny = acct.applyScal(cfg, 1); try std.testing.expectEqual(@as(u32, 1), tiny.capz_send_hour); try std.testing.expectEqual(cfg.capz_send_dayz, acct.applyScal(cfg, 100).capz_send_dayz); }
test "the gap is random inside the configured seconds" { var rng = std.Random.DefaultPrng.init(7); const cfg: conf.Conf = .{}; var ix: u32 = 0; while (ix < 50) : (ix += 1) { const gap = acct.gapMs(&rng, cfg); try std.testing.expect(gap >= 300000 and gap <= 1200000); } }
test "first run moves the old prof and stat into acct/main, never deletes; a second run does nothing" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); const root = try rootOf(&tmp, al); const cwd = std.Io.Dir.cwd(); try cwd.createDirPath(std.testing.io, try std.fmt.allocPrint(al, "{s}/stat", .{root})); try cwd.createDirPath(std.testing.io, try std.fmt.allocPrint(al, "{s}/prof", .{root})); try cwd.writeFile(std.testing.io, .{ .sub_path = try std.fmt.allocPrint(al, "{s}/stat/za-stat.db", .{root}), .data = "DB" }); try cwd.writeFile(std.testing.io, .{ .sub_path = try std.fmt.allocPrint(al, "{s}/prof/Cookies", .{root}), .data = "C" }); try std.testing.expect(try acct.migrate(al, std.testing.io, root)); const txt = try cwd.readFileAlloc(std.testing.io, try std.fmt.allocPrint(al, "{s}/acct/main/stat/za-stat.db", .{root}), al, .limited(100)); try std.testing.expectEqualStrings("DB", txt); _ = try cwd.readFileAlloc(std.testing.io, try std.fmt.allocPrint(al, "{s}/acct/main/prof/Cookies", .{root}), al, .limited(100)); try std.testing.expect(!(try acct.migrate(al, std.testing.io, root))); try std.testing.expectError(error.FileNotFound, cwd.access(std.testing.io, try std.fmt.allocPrint(al, "{s}/stat", .{root}), .{})); }
test "all runs the accounts one by one in rotated order with a gap between them; exit codes are kept" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); naps = 0; var fk: Fake = .{ .aren = al, .root = try rootOf(&tmp, al), .code_id = "c", .code = 3 }; var rng = std.Random.DefaultPrng.init(3); const ids = [_][]const u8{ "a", "b", "c" }; var env = envOf(&fk, al, &ids, 86400000, &rng); const res = try acct.runAll(&env); try std.testing.expectEqual(@as(usize, 3), res.len); try std.testing.expectEqualStrings("b", fk.seen.items[0]); try std.testing.expectEqualStrings("c", fk.seen.items[1]); try std.testing.expectEqualStrings("a", fk.seen.items[2]); try std.testing.expectEqual(@as(u32, 2), naps); try std.testing.expectEqualStrings("exit 3", res[1].state); try std.testing.expectEqual(@as(u8, 3), acct.worst(res)); }
test "a safety stop halts only that account; the next run skips it, the others still run; an owner pause is not a safety stop" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); naps = 0; var fk: Fake = .{ .aren = al, .root = try rootOf(&tmp, al), .halt_id = "a" }; var rng = std.Random.DefaultPrng.init(3); const ids = [_][]const u8{ "a", "b", "c" }; var env = envOf(&fk, al, &ids, 1000, &rng); const res = try acct.runAll(&env); try std.testing.expectEqual(@as(usize, 3), res.len); try std.testing.expectEqual(@as(u8, 4), acct.worst(res)); try std.testing.expect(acct.kindOf(&env, "a") == .safety); try std.testing.expect(acct.kindOf(&env, "b") == .ok); fk.seen.clearRetainingCapacity(); fk.halt_id = ""; const res2 = try acct.runAll(&env); try std.testing.expectEqual(@as(usize, 2), fk.seen.items.len); var skipped: u32 = 0; for (res2) |rs| { if (std.mem.eql(u8, rs.state, "rest")) skipped += 1; } try std.testing.expectEqual(@as(u32, 1), skipped); try setHalt(al, fk.root, "b", "paused by owner"); try std.testing.expect(acct.kindOf(&env, "b") == .owner); }
test "two accounts halted for safety = no account runs" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); var fk: Fake = .{ .aren = al, .root = try rootOf(&tmp, al) }; var rng = std.Random.DefaultPrng.init(3); const ids = [_][]const u8{ "a", "b", "c" }; try setHalt(al, fk.root, "a", "challenge"); try setHalt(al, fk.root, "b", "captcha"); var env = envOf(&fk, al, &ids, 5000, &rng); const res = try acct.runAll(&env); try std.testing.expectEqual(@as(usize, 0), fk.seen.items.len); for (res) |rs| try std.testing.expectEqualStrings("rest", rs.state); }
test "owner pauses on two accounts do not count as safety stops: the third still runs" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); var fk: Fake = .{ .aren = al, .root = try rootOf(&tmp, al) }; var rng = std.Random.DefaultPrng.init(3); const ids = [_][]const u8{ "a", "b", "c" }; try setHalt(al, fk.root, "a", "paused by owner"); try setHalt(al, fk.root, "b", "stopped by owner"); var env = envOf(&fk, al, &ids, 5000, &rng); _ = try acct.runAll(&env); try std.testing.expectEqual(@as(usize, 1), fk.seen.items.len); try std.testing.expectEqualStrings("c", fk.seen.items[0]); }
test "a safety stop during the run with one account already halted stops the remaining accounts" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); var fk: Fake = .{ .aren = al, .root = try rootOf(&tmp, al), .halt_id = "a" }; var rng = std.Random.DefaultPrng.init(3); const ids = [_][]const u8{ "a", "b", "c", "d" }; try setHalt(al, fk.root, "d", "challenge"); var env = envOf(&fk, al, &ids, 0, &rng); const res = try acct.runAll(&env); try std.testing.expectEqual(@as(usize, 1), fk.seen.items.len); try std.testing.expectEqualStrings("a", fk.seen.items[0]); try std.testing.expectEqualStrings("rest", res[1].state); try std.testing.expectEqualStrings("rest", res[2].state); }
test "commands without the browser run for every account with no gap and no skips" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); naps = 0; var fk: Fake = .{ .aren = al, .root = try rootOf(&tmp, al), .halt_id = "a" }; var rng = std.Random.DefaultPrng.init(3); const ids = [_][]const u8{ "a", "b" }; var env = envOf(&fk, al, &ids, 0, &rng); env.browser = false; const res = try acct.runAll(&env); try std.testing.expectEqual(@as(usize, 2), fk.seen.items.len); try std.testing.expectEqual(@as(usize, 2), res.len); try std.testing.expectEqual(@as(u32, 0), naps); }
